import { createHash } from "node:crypto"; import { readWorkbookFile, utils as XLSXUtils } from "./simple-xlsx.js"; import type { AdRunnerManifest, DeviceTarget, OptimizationMode, Placement, PlacementCandidate, ShareBasis, SharePolicy } from "../specification/types.js"; import type { ParsedBlocks, SpreadsheetRow } from "./parser.js"; import { normalizeRows, parseRows } from "./parser.js"; import { assertMode, validateManifest } from "./validator.js";
export interface SheetInput { sheetName:string; rows:SpreadsheetRow[]; hash:string; changed:boolean; }
export interface WorkbookCompilationInput { path:string; sheets:SheetInput[]; reservedSheets:string[]; }
export interface SiteCompilationResult { sheetName:string; site?:string; manifest?:AdRunnerManifest; errors:string[]; warnings:string[]; hash:string; changed:boolean; }
export interface WorkbookCompilationResult { input:WorkbookCompilationInput; sites:SiteCompilationResult[]; valid:boolean; compiledAt:string; }
const RESERVED=new Set(["_README","_TEMPLATE","_GLOBAL","_TERMS"]); const bool=(v:string|undefined,f=true)=>v===undefined?f:["true","1","yes","on"].includes(String(v).toLowerCase()); const list=(v:string|undefined,f:string[]=[])=>v?String(v).split(",").map(s=>s.trim()).filter(Boolean):f; const num=(v:string|undefined,f:number)=>v===undefined||v===""?f:Number(v);
export function compileRows(rows: SpreadsheetRow[], mode: OptimizationMode = "maximum-revenue", version="dev"): AdRunnerManifest { const r=compileSheet("sheet", rows, mode, version); if(r.errors.length) throw new Error(r.errors.join("\n")); return r.manifest!; }
export function compileSheet(sheetName:string, rows:SpreadsheetRow[], requestedMode?:OptimizationMode, version="dev"): SiteCompilationResult { const warnings:string[]=[]; const hash=createHash("sha256").update(normalizeRows(rows)).digest("hex").slice(0,12); try { const raw=parseRows(rows, requestedMode??"maximum-revenue"); const siteBlock=raw.SITE?.site??{}; const selected=String(siteBlock.default_mode || requestedMode || "maximum-revenue"); assertMode(selected); const mode=selected as OptimizationMode; const blocks=parseRows(rows, mode); const site=blocks.SITE?.site??{}; const manifest:AdRunnerManifest={spec:"ad-runner/1",site:site.site_id||sheetName,version,mode,settings:{enabled:bool(site.enabled,true),lazy_load:bool(site.lazy_load,true),collapse_empty_slots:bool(site.collapse_empty_slots,true),debug:bool(site.debug,false),allow_unsafe_scripts:bool(site.allow_unsafe_scripts,false),observe_dom:bool(site.observe_dom,true),cors_origins:list(site.cors_origins,[])},networks:{},units:{},placements:[],warnings,candidateOrder:{}};
 for(const [id,n] of Object.entries(blocks.NETWORK??{})) manifest.networks[id]={adapter:n.adapter??id,enabled:bool(n.enabled,true),loader:{src:n.loader_src,async:bool(n.loader_async,true),load_once:bool(n.load_once,true),html:n.loader_html,success_message:n.success_message,failure_message:n.failure_message,timeout_ms:num(n.timeout_ms,1500)},allowed_origins:list(n.allowed_origins,[])};
 for(const [id,u] of Object.entries(blocks.UNIT??{})){ const clean:any={}; for(const [k,v] of Object.entries(u)) { if(k.includes("secret")&&!k.endsWith("_ref")) continue; clean[k]=v; } manifest.units[id]={...clean,network:u.network,format:u.format,width:num(u.width,0)||undefined,height:num(u.height,0)||undefined,target_blank:bool(u.target_blank,true),simulated_delay_ms:num(u.simulated_delay_ms,0)||undefined} as any; }
 for(const [id,p] of Object.entries(blocks.PLACEMENT??{})){ const candidates=parseCandidates(id,p,warnings); const placement:Placement={id,anchor:p.anchor,selector:p.selector,insertion:p.insertion as Placement["insertion"]|undefined,devices:list(p.devices,["all"]) as DeviceTarget[],priority:num(p.priority,0),enabled:bool(p.enabled,true),candidates}; manifest.placements.push(placement); manifest.candidateOrder![id]=candidates.map(c=>c.unit); }
 validateManifest(manifest); return {sheetName,site:manifest.site,manifest,errors:[],warnings,hash,changed:true}; } catch(e){ return {sheetName,errors:[String((e as Error).message)],warnings,hash,changed:true}; } }
function parseCandidates(id:string,p:Record<string,string>,warnings:string[]):PlacementCandidate[]{ let raw=p.candidates||p.units||p.unit||""; if(!p.candidates && (p.unit||p.units)) warnings.push(`placement ${id} uses legacy unit/units; use candidates instead.`); const units=list(raw,[]); return units.map((unit,idx)=>({unit,priority:num(p[`${unit}_priority`]??p[`candidate_${idx+1}_priority`],100-idx),timeout_ms:num(p[`${unit}_timeout_ms`]??p[`candidate_${idx+1}_timeout_ms`]??p.timeout_ms,1500),guaranteed:bool(p[`${unit}_guaranteed`]??p[`candidate_${idx+1}_guaranteed`],false)})).sort((a,b)=>b.priority-a.priority); }
export async function readWorkbook(path:string):Promise<WorkbookCompilationInput>{ const wb=await readWorkbookFile(path); const sheets:SheetInput[]=[]; const reservedSheets:string[]=[]; for(const name of wb.SheetNames){ if(RESERVED.has(name)){reservedSheets.push(name); continue;} const raw:any[]=XLSXUtils.sheet_to_json(wb.Sheets[name],{defval:""}); const rows=raw.map((r:any,i:number)=>({ ...r, rowNumber:i+2,block_type:String(r.block_type??""),block_id:String(r.block_id??""),field:String(r.field??""),value:String(r.value??""),aesthetic:String(r.aesthetic??""),maximum_visibility:String(r.maximum_visibility??""),maximum_clicks:String(r.maximum_clicks??""),maximum_revenue:String(r.maximum_revenue??""),notes:String(r.notes??"")})); const hash=createHash("sha256").update(normalizeRows(rows)).digest("hex").slice(0,12); sheets.push({sheetName:name,rows,hash,changed:true}); } return {path,sheets,reservedSheets}; }
export async function compileWorkbook(path:string):Promise<WorkbookCompilationResult>{ const input=await readWorkbook(path); const routingRows=input.sheets.flatMap(s=>s.rows.filter((r:any)=>r.site_id)); const sites=routingRows.length?compileRoutingWorkbook(input,routingRows):input.sheets.map(s=>compileSheet(s.sheetName,s.rows,undefined,s.hash)); return {input,sites,valid:sites.every(s=>!s.errors.length),compiledAt:new Date().toISOString()}; }
function compileRoutingWorkbook(input:WorkbookCompilationInput, rows:any[]):SiteCompilationResult[]{ const grouped=new Map<string,any[]>(); for(const r of rows){ if(String(r.enabled??"true").toLowerCase()==="false") continue; const site=String(r.site_id||"").trim(); if(site) grouped.set(site,[...(grouped.get(site)??[]),r]); } return [...grouped.entries()].map(([site,rs])=>compileRoutingSite(site,rs,input.sheets.find(s=>s.rows.some((r:any)=>r.site_id===site))?.hash??"dev")); }
function compileRoutingSite(site:string, rows:any[], version:string):SiteCompilationResult{ const warnings:string[]=[]; const errors:string[]=[]; const manifest:AdRunnerManifest={spec:"ad-runner/2",site,version,mode:"maximum-revenue",settings:{enabled:true,lazy_load:true,collapse_empty_slots:true,debug:true,observe_dom:true},networks:{},units:{},placements:[],warnings,candidateOrder:{},accounts:{}}; const partnerNames=new Map<string,string>(); const accountOwner=new Map<string,string>(); const slotMap=new Map<string,Placement>(); const lanes=new Map<string,Map<string,any>>(); const shares=new Map<string,number>(); for(const r of rows){ const slot=String(r.slot_id||"").trim(), partner=String(r.partner_id||"").trim(), account=String(r.account_id||"").trim(), network=String(r.network_id||"").trim(), unit=String(r.unit_id||"").trim(); if(!partner) errors.push(`row ${r.rowNumber}: missing partner ID`); if(!account) errors.push(`row ${r.rowNumber}: missing account ID`); if(!slot||!String(r.slot_anchor||"").trim()) errors.push(`row ${r.rowNumber}: missing slot anchor`); const share=Number(r.partner_share??0); if(Number.isNaN(share)||share<0) errors.push(`row ${r.rowNumber}: invalid Share Target`); if(partnerNames.has(partner)&&partnerNames.get(partner)!==String(r.partner_name||partner)) errors.push(`duplicate partner ID with conflicting name: ${partner}`); partnerNames.set(partner,String(r.partner_name||partner)); const acctKey=`${network}:${account}`; if(accountOwner.has(acctKey)&&accountOwner.get(acctKey)!==partner) errors.push(`account assigned to conflicting partners: ${acctKey}`); accountOwner.set(acctKey,partner); if(!["round-robin","weighted-opportunities","confirmed-fills",""] .includes(String(r.share_basis||""))) errors.push(`unknown Share Basis: ${r.share_basis}`); if(!["protected-share","open-yield",""] .includes(String(r.share_policy||""))) errors.push(`unknown share policy: ${r.share_policy}`); const netKey=`${network}__${account}`; manifest.networks[netKey]??={adapter:network||"simulated",enabled:true,loader:{html:String(r.loader_code||"")||undefined,async:true,load_once:true,timeout_ms:Number(r.timeout_ms)||1500}}; manifest.accounts![account]={id:account,partner_id:partner,network_id:network,loader_network:netKey}; if(unit){ manifest.units[unit]={network:netKey,account_id:account,partner_id:partner,format:String(r.format_name||""),width:Number(r.width)||undefined,height:Number(r.height)||undefined,devices:list(String(r.devices||"all"),["all"]) as DeviceTarget[],html:String(r.ad_code||"")||undefined,head_markup:String(r.head_markup||"")||undefined,execute:String(r.initialization_code||"")||undefined,simulated_outcome:(String(r.ad_code||"").includes("data-simulated-outcome=\"no-fill\"")?"no-fill":String(r.ad_code||"").includes("data-simulated-outcome=\"timeout\"")?"timeout":"filled") as any}; }
      if(!slotMap.has(slot)) slotMap.set(slot,{id:slot,anchor:String(r.slot_anchor),devices:["all"],priority:0,enabled:true,candidates:[],format:{name:String(r.format_name||"display"),width:Number(r.width)||0,height:Number(r.height)||0},share_basis:(r.share_basis||"confirmed-fills") as ShareBasis,share_policy:(r.share_policy||"open-yield") as SharePolicy,partners:[]}); const key=`${slot}:${partner}`; if(!lanes.has(slot)) lanes.set(slot,new Map()); const lm=lanes.get(slot)!; const lane=lm.get(partner)??{partner_id:partner,partner_name:String(r.partner_name||partner),share_target:share,lane:[]}; if(lane.lane.some((x:any)=>x.unit===unit)) errors.push(`duplicate unit in one Partner Lane: ${unit}`); if(unit) lane.lane.push({unit,priority:Number(r.network_priority)||0,timeout_ms:Number(r.timeout_ms)||1500,guaranteed:String(r.guaranteed||"false").toLowerCase()==="true",devices:list(String(r.devices||"all"),["all"]) as DeviceTarget[]}); lm.set(partner,lane); shares.set(`${slot}:${partner}`,share); }
 for(const [slot,p] of slotMap){ const ps=[...(lanes.get(slot)?.values()??[])]; if(ps.every((x:any)=>x.share_target===0)) errors.push(`every Share Target equal to zero for ${slot}`); for(const x of ps){ if(!x.lane.length) errors.push(`partner with no Network Steps: ${x.partner_id}`); x.lane.sort((a:any,b:any)=>b.priority-a.priority); } const total=ps.reduce((s:any,x:any)=>s+x.share_target,0); if(total!==100) errors.push(`Share Targets for ${slot} total ${total}, not exactly 100`); if(ps.length<2&&p.share_policy==="open-yield") warnings.push(`Open Yield has no Recovery Pass candidates for ${slot}`); p.partners=ps; p.candidates=ps.flatMap((x:any)=>x.lane); manifest.placements.push(p); manifest.candidateOrder![slot]=p.candidates.map(c=>c.unit); }
 try{ validateManifest(manifest as any); }catch(e){ errors.push(String((e as Error).message)); } return {sheetName:"routing table",site,manifest:errors.length?undefined:manifest,errors,warnings,hash:version,changed:true}; }
export function compileBlocks(blocks: ParsedBlocks, mode: OptimizationMode, version: string): AdRunnerManifest { const rows:SpreadsheetRow[]=[]; for(const [bt,objs] of Object.entries(blocks)) for(const [bid,fields] of Object.entries(objs)) for(const [field,value] of Object.entries(fields)) rows.push({block_type:bt,block_id:bid,field,value,aesthetic:"on",maximum_visibility:"on",maximum_clicks:"on",maximum_revenue:"on"}); return compileRows(rows,mode,version); }
